### Plano de Infraestrutura: S3 Log Storage (Nexus Compliance)

**Especificações Técnicas:**
*   **Nome do Bucket:** `nexus-log-storage-prod`
*   **Região de Compliance:** `us-east-1` (N. Virginia)
*   **Privacidade:** Totalmente privado (Public Access Block habilitado).
*   **Criptografia:** AES-256 (SSE-S3) habilitada por padrão.
*   **Tags de Governança:**
    *   `Organization`: Nexus
    *   `Environment`: Production
    *   `ManagedBy`: Terraform

---

### Código Terraform (HCL)

```hcl
# Configuração do Provedor
provider "aws" {
  region = "us-east-1"
}

# Criação do Bucket de Logs seguindo as normas Nexus
resource "aws_s3_bucket" "log_bucket" {
  bucket = "nexus-log-storage-prod"

  tags = {
    Organization = "Nexus"
    Environment  = "Production"
    ManagedBy    = "Terraform"
    Project      = "LogManagement"
  }

  tags unless = {
    # Exemplo de tag de segurança adicional
    SecurityLevel = "High"
  }
}

# Bloqueio de Acesso Público (Compliance Obrigatório)
resource "aws_s3_bucket_public_access_block" "log_bucket_access" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls       = true
  restrict_public_buckets = true
}

# Criptografia em Repouso
resource "aws_s3_bucket_server_side_encryption_by_default" "log_bucket_encryption" {
  bucket = aws_s3_bucket.log_bucket.id

  bucket_respected_encryption_enabled = true
}

# Versionamento para proteção de logs
resource "aws_s3_bucket_versioning" "log_bucket_versioning" {
  bucket = aws_s3_bucket.log_bucket.id
  versioning = {
    enabled = true
  }
}

# Output para confirmação
output "bucket_arn" {
  value = aws_s3_bucket.log_bucket.arn
}

output "bucket_name" {
  value = aws_s3_bucket.log_bucket.bucket
}
```

